// Vérifier et alerter (Alertes temps réel) : v2026.11.07-1 : Snort et appareils UniFi, réessai si envoi HA échoue, UPS retiré
// Vérifier et alerter : workflow « Alertes temps réel » (toutes les 5 minutes)
// Envoie une notification sur le téléphone (application Home Assistant) quand un problème critique APPARAÎT,
// puis une autre quand il est RÉSOLU. Rien n'est envoyé tant que l'état ne change pas.
// Un problème doit être vu 2 fois de suite (10 min) avant l'alerte, pour éviter les fausses alertes.
// L'UPS n'est pas surveillé ici : l'application UniFi envoie déjà ses propres notifications.
// (ex. Snort qui redémarre quelques secondes après la mise à jour de ses règles).
// IMPORTANT : la mémoire de l'état ne fonctionne que lorsque le workflow est ACTIF (pas avec « Execute workflow »).

// ---------- Réglages (coller les clés ici, jamais dans le chat) ----------
const HA_URL      = 'http://IP_PRIVEE_1:PORT_1';
const HA_TOKEN    = 'A_REMPLIR';              // jeton longue durée (le même que pour Uptime Kuma, ou un nouveau)
const HA_SERVICE  = 'mobile_app_sm_g998w';      // ex. mobile_app_sm_s928w (sans « notify. »)

const PFS_URL     = 'https://IP_PRIVEE_2:PORT_2';
const PFS_KEY     = 'A_REMPLIR';           // même clé que check_pfsense_services

const UNIFI_URL   = 'https://IP_PRIVEE_3';
const UNIFI_KEY   = 'A_REMPLIR';             // même clé que check_unifi

const CONFIRMATIONS = 2;   // nombre de vérifications de suite avant d'alerter (2 x 5 min = 10 min)
// ------------------------------------------------------------------------

const problemes = {};      // clé -> texte du problème
const infos = {};          // retour du nœud (pour vérifier)

// 1) Snort : arrêté sur une interface de pfSense
try {
  const r = await this.helpers.httpRequest({
    method: 'GET', url: PFS_URL + '/api/v2/status/services',
    headers: { 'X-API-Key': PFS_KEY, Accept: 'application/json' },
    skipSslCertificateValidation: true, json: true,
  });
  const marche = s => s.status === true || /^(running|started|active|up)$/i.test(String(s.status));
  const snort = (r.data || []).filter(s => /snort/i.test(String(s.name || '') + ' ' + String(s.description || '')));
  snort.filter(s => s.enabled !== false && !marche(s)).forEach(s => {
    problemes['snort:' + (s.description || s.name)] = 'Snort arrêté sur ' + (s.description || s.name);
  });
  infos.snort = snort.length + ' service(s), ' + snort.filter(marche).length + ' en marche';
} catch (e) {
  problemes['pfsense-api'] = "L'API pfSense ne répond pas (" + String(e.message).slice(0, 80) + ')';
}

// 2) Appareils UniFi hors ligne (switchs, points d'accès, UPS...)
try {
  const h = { 'X-API-Key': UNIFI_KEY, Accept: 'application/json' };
  const sites = await this.helpers.httpRequest({ method: 'GET', url: UNIFI_URL + '/proxy/network/integration/v1/sites', headers: h, skipSslCertificateValidation: true, json: true });
  const site = (sites.data || [])[0];
  const devs = await this.helpers.httpRequest({ method: 'GET', url: UNIFI_URL + '/proxy/network/integration/v1/sites/' + site.id + '/devices?limit=200', headers: h, skipSslCertificateValidation: true, json: true });
  const liste = devs.data || [];
  const passage = ['UPDATING', 'GETTING_READY', 'ADOPTING', 'PENDING_ADOPTION'];
  liste.filter(d => String(d.state).toUpperCase() !== 'ONLINE' && !passage.includes(String(d.state).toUpperCase())).forEach(d => {
    problemes['unifi:' + d.id] = 'UniFi : ' + d.name + ' hors ligne (' + d.state + ')';
  });
  infos.unifi = liste.length + ' appareil(s), ' + liste.filter(d => String(d.state).toUpperCase() === 'ONLINE').length + ' en ligne';

} catch (e) {
  problemes['unifi-api'] = "L'API UniFi ne répond pas (" + String(e.message).slice(0, 80) + ')';
}

const immediat = {};   // problèmes signalés dès la 1re vérification (aucun pour l'instant)

// 3) Comparaison avec l'état précédent (mémoire du workflow)
const memoire = $getWorkflowStaticData('global');
const compte = memoire.compte || {};      // nombre de vérifications de suite où le problème est vu
const alertes = memoire.alertes || {};    // problèmes déjà signalés
const aEnvoyer = [];

for (const [cle, texte] of Object.entries(problemes)) {
  compte[cle] = (compte[cle] || 0) + 1;
  if ((compte[cle] >= CONFIRMATIONS || immediat[cle]) && !alertes[cle]) {
    aEnvoyer.push({ cle, type: 'probleme', titre: '🔴 Homelab : problème', message: texte });
  }
}
for (const cle of Object.keys(compte)) {
  if (!problemes[cle]) {
    if (alertes[cle]) aEnvoyer.push({ cle, type: 'resolu', titre: '🟢 Homelab : résolu', message: alertes[cle] });
    delete compte[cle];
  }
}
memoire.compte = compte;
memoire.alertes = alertes;

// 4) Envoi des notifications par Home Assistant
// Un problème n'est noté « déjà signalé » que si l'envoi a réussi : sinon on réessaie à la prochaine vérification.
const envoyes = [];
for (const n of aEnvoyer) {
  let ok = false, detail = '';
  try {
    const rep = await this.helpers.httpRequest({
      method: 'POST', url: HA_URL + '/api/services/notify/' + HA_SERVICE,
      headers: { Authorization: 'Bearer ' + HA_TOKEN, 'Content-Type': 'application/json' },
      body: { title: n.titre, message: n.message, data: { priority: 'high', ttl: 0 } },
      json: true, returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
    ok = rep.statusCode >= 200 && rep.statusCode < 300;
    if (!ok) detail = 'HTTP ' + rep.statusCode + ' : ' + JSON.stringify(rep.body).slice(0, 150);
  } catch (e) {
    detail = String(e.message).slice(0, 150);
  }
  if (ok) {
    if (n.type === 'probleme') alertes[n.cle] = n.message;
    else delete alertes[n.cle];
    envoyes.push(n.titre + ' : ' + n.message);
  } else {
    if (n.type === 'resolu') delete alertes[n.cle];   // pas de nouvel essai pour un « résolu »
    envoyes.push('ÉCHEC ENVOI (' + detail + ') : ' + n.message);
  }
}
memoire.alertes = alertes;

return [{ json: { verifie_a: new Date().toLocaleString('fr-CA', { timeZone: 'America/Toronto' }), problemes_vus: problemes, deja_signales: alertes, notifications_envoyees: envoyes, infos } }];
